/* Included after the fixture-specific declarations generated by the driver.
 * Compare every output, unchanged input, and both allocation guards. */
#define CU(x) do { cudaError_t e=(x); if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);} }while(0)
static double now_ms(void) { struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec*1e3+t.tv_nsec*1e-6; }
static int equal(float a,float b) {
  if(isnan(a)||isnan(b)) return isnan(a)&&isnan(b);
  if(!isfinite(a)||!isfinite(b)) return a==b;
  if(a==0&&b==0) return signbit(a)==signbit(b);
  return fabs((double)a-b)<=ABS_TOL+REL_TOL*fabs((double)b);
}
enum { GUARD_BYTES = 32 };
static size_t bytes(int a) { return sizes[a]*element_bytes[a]+2*GUARD_BYTES; }
static void *allocation(float *p) { return (unsigned char*)p-GUARD_BYTES; }
static void *slot(int a,const float *p,size_t i) { return (unsigned char*)p+i*element_bytes[a]; }
static int equal_slot(int array,const void *a,const void *b) {
  return integer_arrays[array] ? memcmp(a,b,element_bytes[array])==0 : equal(*(const float*)a,*(const float*)b);
}
static void mismatch(const char *label,int array,size_t index,const void *got,const void *expected) {
  if(integer_arrays[array]) {
    int32_t a,b;
    if(integer_arrays[array]==2) { a=*(const int8_t*)got;b=*(const int8_t*)expected; }
    else { memcpy(&a,got,sizeof(a));memcpy(&b,expected,sizeof(b)); }
    printf("%s array=%d i=%zu got=%d expected=%d\n",label,array,index,a,b);
  } else printf("%s array=%d i=%zu got=%a expected=%a\n",label,array,index,*(const float*)got,*(const float*)expected);
}
int main(int argc,char **argv) {
  float *initial[NA],*host[NA],*device[NA],*reference[NA],*native[NA];
  int kind=argc>1&&!strcmp(argv[1],"edge")?1:argc>1&&!strcmp(argv[1],"zeros")?2:0;
  int paper=PAPER_RECIPE && argc>1 && (!strcmp(argv[1],"paper")||!strcmp(argv[1],"timing"));
  const float edges[]={0.f,-0.f,INFINITY,-INFINITY,NAN,FLT_MAX,-FLT_MAX,FLT_MIN,-FLT_MIN,0x1p-149f,-0x1p-149f,1.f,-1.f,0.25f,-0.25f};
  for(int a=0;a<NA;a++) {
    initial[a]=malloc(bytes(a));host[a]=malloc(bytes(a));reference[a]=malloc(bytes(a));native[a]=malloc(bytes(a));
    CU(cudaMalloc((void**)&device[a],bytes(a)));
    if(!initial[a]||!host[a]||!reference[a]||!native[a]) return 2;
    memset(initial[a],0xa5,bytes(a));
    initial[a]=(float*)((unsigned char*)initial[a]+GUARD_BYTES);
    host[a]=(float*)((unsigned char*)host[a]+GUARD_BYTES);
    reference[a]=(float*)((unsigned char*)reference[a]+GUARD_BYTES);
    native[a]=(float*)((unsigned char*)native[a]+GUARD_BYTES);
    device[a]=(float*)((unsigned char*)device[a]+GUARD_BYTES);
    for(size_t i=0;i<sizes[a];i++) {
      float value=((int)((i*104729+a*613)%8192)-4096)/1024.f;
      if(kind==1)value=edges[(i+3*a)%(sizeof(edges)/sizeof(edges[0]))];
      if(kind==2)value=-0.f;
      if(paper)value=paper_value(a,i);
      if(integer_arrays[a]) {
        const int32_t limits[]={0,1,-1,integer_arrays[a]==2?INT8_MIN:INT32_MIN,integer_arrays[a]==2?INT8_MAX:INT32_MAX,2,-2,integer_arrays[a]==2?63:129};
        int32_t integer=kind==2?0:kind==1?limits[(i+3*a)%8]:(int32_t)(i%5+1)*(i%2?-1:1);
        initialize_integer_metadata(a,i,&integer);
        if(paper)integer=(int32_t)paper_value(a,i);
        if(integer_arrays[a]==2) { int8_t small=(int8_t)integer;memcpy(slot(a,initial[a],i),&small,sizeof(small)); }
        else memcpy(slot(a,initial[a],i),&integer,sizeof(integer));
      } else memcpy(slot(a,initial[a],i),&value,sizeof(value));
    }
  }
  int bad_total=0;
  for(int parameter_case=0;parameter_case<(paper?1:NS?2:1);parameter_case++) {
    /* Distinct values expose argument-order errors and nontrivial intervals. */
    for(int s=0;s<NS;s++) parameters[s]=integer_parameters[s]
      ? (parameter_case ? -3-s : s)
      : (parameter_case ? (-0.75f+0.25f*s) : (0.25f+0.5f*s));
    if(paper)for(int s=0;s<NS;s++)parameters[s]=paper_parameters[s];
    for(int a=0;a<NA;a++) {
      memcpy(allocation(reference[a]),allocation(initial[a]),bytes(a));
      CU(cudaMemcpy(allocation(device[a]),allocation(initial[a]),bytes(a),cudaMemcpyHostToDevice));
    }
    invoke_reference(reference);
    invoke_native(device); complete_native(device); CU(cudaDeviceSynchronize());
    for(int a=0;a<NA;a++) CU(cudaMemcpy(allocation(native[a]),allocation(device[a]),bytes(a),cudaMemcpyDeviceToHost));
    if(argc>1&&!strcmp(argv[1],"timing")) {
      /* Input restoration is outside each measured interval, including in-place operations. */
      for(int i=-5;i<TIMING_SAMPLES;i++) for(int order=0;order<2;order++) {
        int path=order^(i&1);
        for(int a=0;a<NA;a++) CU(cudaMemcpy(allocation(device[a]),allocation(initial[a]),bytes(a),cudaMemcpyHostToDevice));
        CU(cudaDeviceSynchronize()); double start=now_ms();
        if(path)invoke_native(device);else invoke(device);
        CU(cudaDeviceSynchronize());
        if(i>=0)printf("SAMPLE path=%s sample=%d ms=%.9f\n",path?"native_aten_cuda":"raised",i,now_ms()-start);
      }
      puts("PASS timing"); return 0;
    }
    for(int resident=0;resident<2;resident++) {
      for(int a=0;a<NA;a++) {
        memcpy(allocation(host[a]),allocation(initial[a]),bytes(a));
        CU(cudaMemcpy(allocation(device[a]),allocation(initial[a]),bytes(a),cudaMemcpyHostToDevice));
      }
      invoke(resident?device:host); CU(cudaDeviceSynchronize());
      if(resident) for(int a=0;a<NA;a++) CU(cudaMemcpy(allocation(host[a]),allocation(device[a]),bytes(a),cudaMemcpyDeviceToHost));
      size_t count=0,bad=0,nativebad=0,nativerefbad=0,guardbad=0,inputbad=0; double maxabs=0;
      for(int a=0;a<NA;a++) {
        for(int j=0;j<GUARD_BYTES;j++) {
          unsigned char *h=allocation(host[a]),*n=allocation(native[a]);
          size_t end=GUARD_BYTES+sizes[a]*element_bytes[a]+j;
          if(h[j]!=0xa5||h[end]!=0xa5||n[j]!=0xa5||n[end]!=0xa5)guardbad++;
        }
        for(size_t i=0;i<sizes[a];i++) {
          const void *h=slot(a,host[a],i),*r=slot(a,reference[a],i),*n=slot(a,native[a],i);
          if(outputs[a]) {
            count++;
            if(!integer_arrays[a]&&isfinite(*(const float*)h)&&isfinite(*(const float*)r))maxabs=fmax(maxabs,fabs((double)*(const float*)h-*(const float*)r));
            if(!equal_slot(a,h,r)) { if(bad<4)mismatch("MISMATCH",a,i,h,r);bad++; }
            if(!equal_slot(a,h,n)) { if(nativebad<4)mismatch("NATIVE_MISMATCH",a,i,h,n);nativebad++; }
            if(!equal_slot(a,n,r)) { if(nativerefbad<4)mismatch("NATIVE_REFERENCE_MISMATCH",a,i,n,r);nativerefbad++; }
          } else if(memcmp(h,slot(a,initial[a],i),element_bytes[a])||memcmp(n,slot(a,initial[a],i),element_bytes[a])) inputbad++;
        }
      }
      printf("CHECK kind=%d parameters=%d resident=%d count=%zu bad=%zu nativebad=%zu nativerefbad=%zu guardbad=%zu inputbad=%zu maxabs=%.9g\n",kind,parameter_case,resident,count,bad,nativebad,nativerefbad,guardbad,inputbad,maxabs);
      bad_total|=bad||nativebad||nativerefbad||guardbad||inputbad;
    }
  }
  if(bad_total)return 3;
  puts("PASS correctness");return 0;
}
